#!/usr/bin/env python3
"""Print the first N Fibonacci numbers. Usage: python fibonacci.py [N]"""
import sys


def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b


if __name__ == "__main__":
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    print(*fib(n))
